let PAGE_TITLE=document.title,SIGNATURE=/^[a-zA-Z]+\(.*\)$/,BACKTICKS=/`/g,HELPERS_LABEL="Helpers",sidebarLabel=e=>e.includes("), ")?HELPERS_LABEL:e.slice(0,e.indexOf("("))+"()",markSignatures=()=>{document.querySelectorAll(".markdown-section h3").forEach(e=>{SIGNATURE.test(e.textContent.trim())&&e.classList.add("signature")}),document.querySelectorAll(".sidebar-nav a").forEach(e=>{var t=e.textContent.trim();SIGNATURE.test(t)&&(t=sidebarLabel(t),(e.textContent=t)!==HELPERS_LABEL)&&e.classList.add("signature")})},replaceInTextNodes=(e,t)=>{for(var r=document.createTreeWalker(e,window.NodeFilter.SHOW_TEXT);r.nextNode();)r.currentNode.nodeValue=t(r.currentNode.nodeValue)},withoutBackticks=e=>e.replace(BACKTICKS,""),cleanSearchResults=e=>{e.querySelectorAll(".matching-post .title").forEach(e=>replaceInTextNodes(e,withoutBackticks)),e.querySelectorAll(".matching-post .content").forEach(e=>replaceInTextNodes(e,withoutBackticks))},watchSearchResults=()=>{let e=document.querySelector(".search .results-panel");e&&new window.MutationObserver(()=>cleanSearchResults(e)).observe(e,{childList:!0})},enhancePage=()=>{document.querySelector("#seo-content")?.remove(),markSignatures(),window.codecopy("pre")};window.$docsify={name:"onesecret",repo:"kikobeats/onesecret",maxLevel:3,auto2top:!0,noEmoji:!0,externalLinkRel:"noopener noreferrer",pageTitleFormatter:()=>PAGE_TITLE,search:{maxAge:0,placeholder:"Search",noData:"No results",depth:3},plugins:[e=>{e.doneEach(enhancePage),e.ready(watchSearchResults)}]};